//! The JIR (Just-in-time Intermediate Representation) is generated by the [SleighCompiler] and intended for use
//! with a just-in-time compiler like the one in mogi_cpu

pub mod basic_block;
pub mod common;
pub mod context_stack;
pub mod custom_op;
pub mod jcode;
pub mod jir_block;
pub mod jumplist;
pub mod local_resolver;
pub mod space;
pub mod values;

#[cfg(feature = "trace_jir")]
macro_rules! trace_jir {
    ($($arg:tt)*) => {
        tracing::trace!($($arg)*)
    };
}
#[cfg(not(feature = "trace_jir"))]
macro_rules! trace_jir {
    ($($arg:tt)*) => {};
}

#[cfg(feature = "trace_match")]
macro_rules! trace_match {
    ($($arg:tt)*) => {
        tracing::trace!($($arg)*)
    };
}
#[cfg(not(feature = "trace_match"))]
macro_rules! trace_match {
    ($($arg:tt)*) => {};
}

pub(crate) use trace_jir;
pub(crate) use trace_match;
